func TestRawClient_Do_RetriesSeekableFileBodyOn429(t *testing.T) {
	t.Parallel()

	var (
		mu      sync.Mutex
		calls   int
		gotBody []byte
	)
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		body, _ := io.ReadAll(req.Body)

		mu.Lock()
		defer mu.Unlock()
		calls++
		gotBody = body
		status := http.StatusTooManyRequests
		if calls == 2 {
			status = http.StatusOK
		}
		return &http.Response{
			StatusCode: status,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader(`{"ok":true}`)),
			Request:    req,
		}, nil
	})

	policy := DefaultRetryPolicy()
	policy.MaxAttempts = 3
	policy.BaseDelay = time.Millisecond
	policy.MaxDelay = time.Millisecond
	policy.Jitter = func(d time.Duration) time.Duration { return d }

	client := &http.Client{Transport: newRetryTransport(next, policy, retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   func() time.Time { return time.Unix(0, 0).UTC() },
	})}
	raw, err := NewRawClient("https://example.test", client)
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	f, err := os.CreateTemp(t.TempDir(), "raw-*.txt")
	if err != nil {
		t.Fatalf("create temp file: %v", err)
	}
	t.Cleanup(func() { _ = f.Close() })
	if _, err := f.WriteString("payload"); err != nil {
		t.Fatalf("write temp file: %v", err)
	}
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		t.Fatalf("seek temp file: %v", err)
	}

	var out struct {
		Ok bool `json:"ok"`
	}
	if err := raw.Do(context.Background(), http.MethodPost, "/files", nil, f, &out); err != nil {
		t.Fatalf("Do error: %v", err)
	}
	if !out.Ok {
		t.Fatalf("expected ok=true")
	}

	mu.Lock()
	defer mu.Unlock()
	if calls != 2 {
		t.Fatalf("expected 2 calls (retry), got %d", calls)
	}
	if string(gotBody) != "payload" {
		t.Fatalf("expected body to be replayed, got %q", string(gotBody))
	}
}

