func TestFilesService_Upload(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if ct := r.Header.Get("Content-Type"); !strings.HasPrefix(ct, "multipart/form-data;") {
			t.Fatalf("unexpected content type: %q", ct)
		}
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Fatalf("parse multipart: %v", err)
		}
		file, hdr, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("form file: %v", err)
		}
		data, err := io.ReadAll(file)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		if hdr.Filename != "doc.pdf" {
			t.Fatalf("unexpected filename: %q", hdr.Filename)
		}
		if string(data) != "pdf-bytes" {
			t.Fatalf("unexpected file data: %q", string(data))
		}
		if got := r.Form.Get("deal_id"); got != "5" {
			t.Fatalf("unexpected deal_id: %q", got)
		}
		if got := r.Form.Get("person_id"); got != "7" {
			t.Fatalf("unexpected person_id: %q", got)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"doc.pdf"}}`))
	})

	file, err := client.Files.Upload(
		context.Background(),
		"doc.pdf",
		strings.NewReader("pdf-bytes"),
		WithFileDealID(DealID(5)),
		WithFilePersonID(PersonID(7)),
	)
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 || file.Name != "doc.pdf" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

