	var (
		mu      sync.Mutex
		calls   int
		gotBody string
	)
	cfg := pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts:     3,
			BaseDelay:       time.Millisecond,
			MaxDelay:        time.Millisecond,
			Jitter:          func(d time.Duration) time.Duration { return d },
			RetryAllMethods: true,
		},
	}
	client := newTestClientWithConfig(t, cfg, func(w http.ResponseWriter, r *http.Request) {
		data, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read body: %v", err)
		}

		mu.Lock()
		defer mu.Unlock()
		calls++
		gotBody = string(data)
		if calls == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	f, err := os.CreateTemp(t.TempDir(), "upload-*.txt")
	if err != nil {
		t.Fatalf("create temp file: %v", err)
