+func TestFilesService_Add_RetriesOnRateLimitWithFileBody(t *testing.T) {
+	t.Parallel()
+
+	var (
+		mu      sync.Mutex
+		calls   int
+		gotBody string
+	)
+	cfg := pipedrive.Config{
+		RetryPolicy: &pipedrive.RetryPolicy{
+			MaxAttempts:     3,
+			BaseDelay:       time.Millisecond,
+			MaxDelay:        time.Millisecond,
+			Jitter:          func(d time.Duration) time.Duration { return d },
+			RetryAllMethods: true,
+		},
+	}
+	client := newTestClientWithConfig(t, cfg, func(w http.ResponseWriter, r *http.Request) {
+		data, err := io.ReadAll(r.Body)
+		if err != nil {
+			t.Errorf("read body: %v", err)
+		}
+
+		mu.Lock()
+		defer mu.Unlock()
+		calls++
+		gotBody = string(data)
+		if calls == 1 {
+			w.WriteHeader(http.StatusTooManyRequests)
+			return
+		}
+		w.Header().Set("Content-Type", "application/json")
+		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
+	})
+
+	f, err := os.CreateTemp(t.TempDir(), "upload-*.txt")
+	if err != nil {
+		t.Fatalf("create temp file: %v", err)
+	}
+	t.Cleanup(func() { _ = f.Close() })
+	if _, err := f.WriteString("file-content"); err != nil {
+		t.Fatalf("write temp file: %v", err)
+	}
+	if _, err := f.Seek(0, io.SeekStart); err != nil {
+		t.Fatalf("seek temp file: %v", err)
+	}
+
+	file, err := client.Files.Add(context.Background(), f, "application/octet-stream")
+	if err != nil {
+		t.Fatalf("Add error: %v", err)
+	}
+	if file.ID != 12 {
+		t.Fatalf("unexpected file: %#v", file)
+	}
+
+	mu.Lock()
+	defer mu.Unlock()
+	if calls != 2 {
+		t.Fatalf("expected 2 calls (retry), got %d", calls)
+	}
+	if gotBody != "file-content" {
+		t.Fatalf("expected body to be replayed, got %q", gotBody)
+	}
+}
