// makeBodyReplayable wires up req.GetBody so the retry transport can replay
// the request body across retries. http.NewRequest only sets GetBody for
// in-memory types (bytes.Buffer, bytes.Reader, strings.Reader); arbitrary
// io.Readers such as *os.File get a Body but no GetBody, which would make
// the retry transport skip retries entirely. This handles:
//
//   - io.Seeker bodies by remembering their start offset and seeking back to
//     it on each replay, so files can be uploaded without buffering them into
//     memory;
//   - everything else by buffering the body into memory once so it can be
//     replayed from the buffer.
func makeBodyReplayable(req *http.Request, body any) {
	if req.GetBody != nil || req.Body == nil || req.Body == http.NoBody {
		return
	}

	if seeker, ok := body.(io.Seeker); ok {
		start, err := seeker.Seek(0, io.SeekCurrent)
		if err != nil {
			return
		}
		req.GetBody = func() (io.ReadCloser, error) {
			if _, err := seeker.Seek(start, io.SeekStart); err != nil {
				return nil, err
			}
			return io.NopCloser(req.Body), nil
		}
		return
	}

	buf, err := io.ReadAll(req.Body)
	if err != nil {
		return
	}
	req.Body = io.NopCloser(bytes.NewReader(buf))
	req.ContentLength = int64(len(buf))
	req.GetBody = func() (io.ReadCloser, error) {
		return io.NopCloser(bytes.NewReader(buf)), nil
	}
}

